async function runJob() {
  const ok = await redis.set('job-lock', id, 'NX', 'PX', 10000);
  if (!ok) return;                 // someone else holds it
  await chargeAllSubscriptions();  // writes directly to the billing DB, no token
  await redis.del('job-lock');
}

