let isLeader = false;

async function tryBecomeLeader() {
  const ok = await coord.acquire('leader', { ttl: 10 });  // 10s lease
  if (ok) {
    isLeader = true;
    setInterval(() => coord.renew('leader'), 10000);       // renew every 10s
  }
}

async function runLoop() {
  while (true) {
    if (isLeader) {
      await doSingularJob();    // assumes we're still leader; no token
    }
    await tick();
  }
}
